package org.jsoup.helper;

import org.jsoup.Connection;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.junit.runners.JUnit4;
import org.mockito.Mockito;

@RunWith(JUnit4.class)
public class UrlBuilderTest {

    @Test
    public void ofUrl_withValidUrl_shouldReturnSameUrl() {
        // Arrange and Act
        UrlBuilder urlBuilder = new UrlBuilder(new URL("https://example.com"));
        String actual = urlBuilder.build().toString();

        // Assert
        org.junit.Assert.assertEquals("https://example.com", actual);
    }

    @Test
    public void ofUrl_withInvalidUrl_shouldThrowMalformedURLException() {
        // Arrange and Act and Assert
        org.junit.Assert.assertThrows(MalformedURLException.class, () -> new UrlBuilder(new URL("invalid://url")));
    }

    @Test
    public void appendKeyVal_withValidKeyVal_shouldAppendToUrlCorrectly() throws UnsupportedEncodingException {
        // Arrange
        Connection.KeyVal kv = new Connection.KeyVal(URI.create("https://example.com"), "key", "value");
        UrlBuilder urlBuilder = new UrlBuilder(new URL("https://example.com"));
        String expectedUrl = "https://example.com?key=value";

        // Act and Assert
        urlBuilder.appendKeyVal(kv);
        String actual = urlBuilder.build().toString();
        org.junit.Assert.assertEquals(expectedUrl, actual);
    }

    @Test
    public void appendKeyVal_withNullKeyVal_shouldNotAppendToUrl() throws UnsupportedEncodingException {
        // Arrange
        UrlBuilder urlBuilder = new UrlBuilder(new URL("https://example.com"));
        Connection.KeyVal kv = null;

        // Act and Assert
        urlBuilder.appendKeyVal(kv);
        String actual = urlBuilder.build().toString();
        org.junit.Assert.assertEquals("https://example.com", actual);
    }

    @Test
    public void appendKeyVal_withInvalidKeyVal_shouldThrowUnsupportedEncodingException() throws UnsupportedEncodingException {
        // Arrange and Act and Assert
        org.junit.Assert.assertThrows(UnsupportedEncodingException.class, () -> new UrlBuilder(new URL("https://example.com")).appendKeyVal(null));
    }
}
